import { useRender } from '@base-ui/react/use-render';
import type { VariantProps } from 'class-variance-authority';
import type React from 'react';
import { badgeVariants } from '@/components/ui/shared/badge-variants';
import { asChildToRender } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn } from '@/registry/base-nova/protoform/lib/utils';
import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

export type BadgeVariant = VariantProps<typeof badgeVariants>['variant'];
export type BadgeSize = VariantProps<typeof badgeVariants>['size'];

function Badge({
  className,
  variant,
  asChild = false,
  testId,
  icon,
  children,
  size,
  ref,
  render,
  ...props
}: useRender.ComponentProps<'span'> &
  SharedProps & {
    asChild?: boolean;
    icon?: React.ReactNode;
    variant?: BadgeVariant;
    size?: BadgeSize;
  }) {
  const childProps = asChildToRender({ asChild, children, render });

  const renderContent = () => {
    if (asChild === true) {
      return children;
    }

    if (icon && children) {
      return (
        <>
          {icon}
          <span className="truncate">{children}</span>
        </>
      );
    }

    if (icon) {
      return icon;
    }

    if (children) {
      return <span className="truncate">{children}</span>;
    }

    return null;
  };

  return useRender({
    defaultTagName: 'span',
    render: childProps.render,
    ref,
    props: {
      ...props,
      className: cn(badgeVariants({ size, variant }), className),
      'data-slot': 'badge',
      'data-testid': testId,
      children: asChild === true ? undefined : renderContent(),
    },
  });
}

export { badgeVariants } from '@/components/ui/shared/badge-variants';
export { Badge };

'use client';

import { Button as ButtonPrimitive } from '@base-ui/react/button';
import { cva, type VariantProps } from 'class-variance-authority';
import React, { type ElementType } from 'react';

import { useGroup } from '@/components/ui/group';
import { buttonStyleOptions } from '@/components/ui/shared/button-variants';
import { Spinner } from '@/components/ui/spinner';
import { Slot } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn } from '@/registry/base-nova/protoform/lib/utils';
import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const buttonVariants = cva(
  [
    'group/button inline-flex shrink-0 items-center justify-center',
    'rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap',
    'transition-all outline-none select-none',
    'cursor-pointer',
    'data-[slot=help-trigger]:rounded-full data-[slot=help-trigger]:text-muted-foreground data-[slot=help-trigger]:shadow-none data-[slot=help-trigger]:hover:text-foreground',
    'disabled:pointer-events-none disabled:cursor-not-allowed',
    'disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:cursor-not-allowed aria-disabled:opacity-50',
    'focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50',
    'aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20',
    'dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
    'selection:bg-selected selection:text-selected-foreground',
    'active:not-aria-[haspopup]:translate-y-px',
    '[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
  ],
  buttonStyleOptions
);

export type ButtonVariants = VariantProps<typeof buttonVariants>;

export type ButtonProps = ButtonPrimitive.Props &
  ButtonVariants & {
    asChild?: boolean | undefined;
    as?: ElementType | undefined;
    to?: string | undefined;
    icon?: React.ReactNode | undefined;
    isLoading?: boolean | undefined;
    href?: string | undefined;
    target?: string | undefined;
    rel?: string | undefined;
  } & SharedProps;

function ButtonContent({ children, icon, isLoading }: Pick<ButtonProps, 'children' | 'icon' | 'isLoading'>) {
  const content = icon ? (
    <>
      {children}
      {icon}
    </>
  ) : (
    children
  );
  if (isLoading === true) {
    return (
      <>
        <span className="invisible contents">{content}</span>
        <span aria-hidden="true" className="absolute inset-0 flex items-center justify-center">
          <Spinner />
        </span>
      </>
    );
  }
  return content;
}

type ButtonStyleProps = Pick<ButtonProps, 'className' | 'variant' | 'size' | 'icon' | 'isLoading'> & {
  positionClasses: string;
};

function getButtonClasses(
  { className, variant, size, icon, isLoading, positionClasses }: ButtonStyleProps,
  state: ButtonPrimitive.State
) {
  return cn(
    buttonVariants({ size, variant }),
    positionClasses,
    icon && 'gap-2',
    isLoading === true && 'relative',
    typeof className === 'function' ? className(state) : className
  );
}

function getButtonPositionClasses(attached: boolean, position: ReturnType<typeof useGroup>['position']) {
  if (!attached) {
    return 'rounded-lg';
  }
  if (position === 'first') {
    return 'rounded-r-none rounded-l-lg border-r-0';
  }
  if (position === 'last') {
    return 'rounded-r-lg rounded-l-none border-l-0';
  }
  if (position === 'middle') {
    return 'rounded-none border-r-0 border-l-0';
  }
  return 'rounded-lg';
}

function LegacyButton({
  as,
  asChild,
  children,
  className,
  variant,
  size,
  icon,
  isLoading,
  positionClasses,
  disabled,
  style,
  focusableWhenDisabled: _focusableWhenDisabled,
  ...props
}: ButtonProps & { positionClasses: string }) {
  const Component = as ?? Slot;
  const state: ButtonPrimitive.State = { disabled: disabled === true };
  return React.createElement(
    Component,
    {
      ...props,
      className: getButtonClasses({ className, variant, size, icon, isLoading, positionClasses }, state),
      disabled,
      style: typeof style === 'function' ? style(state) : style,
    },
    asChild === true ? (
      children
    ) : (
      <ButtonContent icon={icon} isLoading={isLoading}>
        {children}
      </ButtonContent>
    )
  );
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      testId,
      as,
      to,
      icon,
      isLoading = false,
      disabled,
      children,
      render,
      nativeButton,
      type = 'button',
      ...props
    },
    ref
  ) => {
    const { attached, position } = useGroup();
    const isDisabled = disabled === true || isLoading;
    const positionClasses = getButtonPositionClasses(attached, position);
    const shared = {
      'aria-busy': isLoading === true ? true : undefined,
      'data-loading': isLoading === true ? true : undefined,
      'data-slot': 'button',
      'data-testid': testId,
      disabled: isDisabled,
      ref,
      type,
    } as const;
    const styleProps = { className, variant, size, icon, isLoading, positionClasses };
    if (asChild === true || as !== undefined) {
      return (
        <LegacyButton {...shared} {...props} {...styleProps} as={as} asChild={asChild} to={to}>
          {children}
        </LegacyButton>
      );
    }
    return (
      <ButtonPrimitive
        {...shared}
        {...props}
        className={(state) => getButtonClasses(styleProps, state)}
        nativeButton={nativeButton}
        render={render}
      >
        <ButtonContent icon={icon} isLoading={isLoading}>
          {children}
        </ButtonContent>
      </ButtonPrimitive>
    );
  }
);

Button.displayName = 'Button';

export { Button, buttonVariants };

'use client';

import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from 'lucide-react';
import React from 'react';
import { type DayButton, DayPicker, getDefaultClassNames, type Locale } from 'react-day-picker';

import { Button, buttonVariants } from '@/components/ui/button';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const CalendarLocaleContext = React.createContext<Partial<Locale> | undefined>(undefined);

function CalendarRoot({
  className,
  rootRef,
  ...props
}: React.ComponentProps<'div'> & { rootRef?: React.Ref<HTMLDivElement> }) {
  return <div className={cn(className)} data-slot="calendar" ref={rootRef} {...props} />;
}

function CalendarChevron({
  className,
  orientation,
  ...props
}: {
  className?: string;
  orientation?: 'left' | 'right' | 'down' | 'up';
}) {
  if (orientation === 'left') {
    return <ChevronLeftIcon className={cn('size-4', className)} {...props} />;
  }

  if (orientation === 'right') {
    return <ChevronRightIcon className={cn('size-4', className)} {...props} />;
  }

  return <ChevronDownIcon className={cn('size-4', className)} {...props} />;
}

function CalendarWeekNumber({ children, ...props }: React.ComponentProps<'td'>) {
  return (
    <td {...props}>
      <div className="flex size-(--cell-size) items-center justify-center text-center">{children}</div>
    </td>
  );
}

const CalendarRootWithTestId = React.memo(
  ({ testId, ...props }: React.ComponentProps<typeof CalendarRoot> & { testId?: string | undefined }) => (
    <CalendarRoot {...props} data-testid={testId} />
  )
);

CalendarRootWithTestId.displayName = 'CalendarRootWithTestId';

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = 'label',
  buttonVariant = 'ghost',
  formatters,
  locale,
  components,
  testId,
  ...props
}: React.ComponentProps<typeof DayPicker> &
  SharedProps & {
    buttonVariant?: React.ComponentProps<typeof Button>['variant'];
  }) {
  'use no memo';

  const defaultClassNames = getDefaultClassNames();

  const rootComponent = React.useMemo(
    () =>
      Object.assign(
        ({ ref, ...rootProps }: React.ComponentProps<typeof CalendarRoot> & { ref?: React.Ref<HTMLDivElement> }) => (
          <CalendarRootWithTestId {...rootProps} rootRef={ref ?? null} testId={testId} />
        ),
        { displayName: 'CalendarRootComponent' }
      ),
    [testId]
  );

  return (
    <CalendarLocaleContext.Provider value={locale}>
      <DayPicker
        captionLayout={captionLayout}
        className={cn(
          'group/calendar bg-background p-3 [--cell-size:--spacing(8)] [&:is([data-slot=card-content]_*)]:bg-transparent [&:is([data-slot=popover-content]_*)]:bg-transparent',
          String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
          String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
          className
        )}
        classNames={{
          button_next: cn(
            buttonVariants({ variant: buttonVariant }),
            'size-(--cell-size) p-0 select-none aria-disabled:opacity-50',
            defaultClassNames.button_next
          ),
          button_previous: cn(
            buttonVariants({ variant: buttonVariant }),
            'size-(--cell-size) p-0 select-none aria-disabled:opacity-50',
            defaultClassNames.button_previous
          ),
          caption_label: cn(
            'font-medium select-none',
            captionLayout === 'label'
              ? 'text-sm'
              : 'flex h-8 items-center gap-1 rounded-md pr-1 pl-2 text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground',
            defaultClassNames.caption_label
          ),
          day: cn(
            'group/day relative aspect-square size-full p-0 text-center select-none [&:first-child[data-selected=true]_button]:rounded-l-md [&:last-child[data-selected=true]_button]:rounded-r-md',
            defaultClassNames.day
          ),
          disabled: cn('text-muted-foreground opacity-50', defaultClassNames.disabled),
          dropdown: cn('absolute inset-0 opacity-0', defaultClassNames.dropdown),
          dropdown_root: cn(
            'relative rounded-md border !border-input shadow-xs has-focus:border-ring has-focus:ring-3 has-focus:ring-ring/50',
            defaultClassNames.dropdown_root
          ),
          dropdowns: cn(
            'flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium',
            defaultClassNames.dropdowns
          ),
          hidden: cn('invisible', defaultClassNames.hidden),
          month: cn('flex w-full flex-col gap-4', defaultClassNames.month),
          month_caption: cn(
            'flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)',
            defaultClassNames.month_caption
          ),
          months: cn('relative flex flex-col gap-4 md:flex-row', defaultClassNames.months),
          nav: cn('absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1', defaultClassNames.nav),
          outside: cn('text-muted-foreground aria-selected:text-muted-foreground', defaultClassNames.outside),
          range_end: cn('rounded-r-md bg-accent', defaultClassNames.range_end),
          range_middle: cn('rounded-none', defaultClassNames.range_middle),
          range_start: cn('rounded-l-md bg-accent', defaultClassNames.range_start),
          root: cn('w-fit', defaultClassNames.root),
          today: cn(
            'rounded-md bg-accent text-accent-foreground data-[selected=true]:rounded-none',
            defaultClassNames.today
          ),
          week: cn('mt-2 flex w-full', defaultClassNames.week),
          week_number: cn('text-xs text-muted-foreground select-none', defaultClassNames.week_number),
          week_number_header: cn('w-(--cell-size) select-none', defaultClassNames.week_number_header),
          weekday: cn(
            'flex-1 rounded-md text-xs font-normal text-muted-foreground select-none',
            defaultClassNames.weekday
          ),
          weekdays: cn('flex', defaultClassNames.weekdays),
          ...classNames,
        }}
        components={{
          Chevron: CalendarChevron,
          DayButton: CalendarDayButton,
          Root: rootComponent,
          WeekNumber: CalendarWeekNumber,
          ...components,
        }}
        formatters={{
          formatMonthDropdown: (date) => date.toLocaleString(locale?.code, { month: 'short' }),
          ...formatters,
        }}
        locale={locale}
        showOutsideDays={showOutsideDays}
        {...props}
      />
    </CalendarLocaleContext.Provider>
  );
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  locale,
  ...props
}: React.ComponentProps<typeof DayButton> & { locale?: Partial<Locale> | undefined }) {
  const inheritedLocale = React.useContext(CalendarLocaleContext);
  const effectiveLocale = locale ?? inheritedLocale;
  const isFocused = modifiers['focused'];

  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(
    function focusActiveDay() {
      if (isFocused) {
        ref.current?.focus();
      }
    },
    [isFocused]
  );

  return (
    <Button
      className={cn(className)}
      data-day={day.date.toLocaleDateString(effectiveLocale?.code)}
      data-range-end={modifiers['range_end']}
      data-range-middle={modifiers['range_middle']}
      data-range-start={modifiers['range_start']}
      data-selected-single={
        modifiers['selected'] && !modifiers['range_start'] && !modifiers['range_end'] && !modifiers['range_middle']
      }
      ref={ref}
      size="icon"
      variant="calendar"
      {...props}
    />
  );
}

export { Calendar, CalendarDayButton };

export type { CardProps, CardSize, CardVariant } from '@/components/ui/shared/card';
export {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardField,
  CardFooter,
  CardForm,
  CardHeader,
  CardTitle,
} from '@/components/ui/shared/card';

'use client';

import { Checkbox as CheckboxPrimitive } from '@base-ui/react/checkbox';
import { cva, type VariantProps } from 'class-variance-authority';
import { type HTMLMotionProps, motion } from 'motion/react';
import type React from 'react';
import { useState } from 'react';

import { splitMotionProps } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const pathDrawClassName =
  '[stroke-dasharray:1] [stroke-dashoffset:1] opacity-0 transition-[stroke-dashoffset,opacity] duration-200 ease-out data-[visible=true]:[stroke-dashoffset:0] data-[visible=true]:opacity-100 data-[visible=true]:delay-100';

const checkboxVariants = cva(
  'peer relative flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-sm border transition-colors outline-none after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 motion-safe:hover:scale-105 motion-safe:active:scale-95 dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
  {
    defaultVariants: {
      variant: 'primary',
    },
    variants: {
      variant: {
        outline:
          '!border-input data-[state=checked]:border-foreground data-[state=checked]:bg-transparent data-[state=checked]:text-foreground data-[state=indeterminate]:border-foreground data-[state=indeterminate]:bg-transparent data-[state=indeterminate]:text-foreground',
        primary:
          '!border-input data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground data-[state=indeterminate]:border-primary data-[state=indeterminate]:bg-primary data-[state=indeterminate]:text-primary-foreground',
        secondary:
          '!border-input data-[state=checked]:border-secondary data-[state=checked]:bg-secondary data-[state=checked]:text-primary-foreground data-[state=indeterminate]:border-secondary data-[state=indeterminate]:bg-secondary data-[state=indeterminate]:text-primary-foreground',
      },
    },
  }
);

type PrimitiveCheckboxProps = React.ComponentProps<typeof CheckboxPrimitive.Root>;
type CheckboxProps = Omit<PrimitiveCheckboxProps, 'checked' | 'defaultChecked'> &
  Omit<HTMLMotionProps<'button'>, keyof PrimitiveCheckboxProps> &
  VariantProps<typeof checkboxVariants> &
  SharedProps & {
    checked?: boolean | 'indeterminate' | undefined;
    defaultChecked?: boolean | 'indeterminate' | undefined;
  };

function Checkbox({
  className,
  variant,
  testId,
  checked,
  defaultChecked,
  indeterminate,
  onCheckedChange,
  nativeButton,
  render,
  children,
  ...props
}: CheckboxProps) {
  const [uncontrolledIndeterminate, setUncontrolledIndeterminate] = useState(defaultChecked === 'indeterminate');
  const handleCheckedChange: NonNullable<PrimitiveCheckboxProps['onCheckedChange']> = (next, details) => {
    onCheckedChange?.(next, details);
    if (!details.isCanceled && checked === undefined) {
      setUncontrolledIndeterminate(false);
    }
  };
  const separated = splitMotionProps(props);
  const renderRoot: NonNullable<PrimitiveCheckboxProps['render']> = (rootProps, state) => {
    const Root: React.ElementType = nativeButton === false ? 'span' : 'button';
    let dataState = 'unchecked';
    if (state.checked) {
      dataState = 'checked';
    }
    if (state.indeterminate) {
      dataState = 'indeterminate';
    }
    return <Root {...rootProps} data-state={dataState} />;
  };
  return (
    <CheckboxPrimitive.Root
      {...separated.native}
      checked={checked === 'indeterminate' ? false : checked}
      className={(state) =>
        cn(checkboxVariants({ variant }), typeof className === 'function' ? className(state) : className)
      }
      data-slot="checkbox"
      data-testid={testId}
      defaultChecked={defaultChecked === 'indeterminate' ? false : defaultChecked}
      indeterminate={
        indeterminate ?? (checked === 'indeterminate' || (checked === undefined && uncontrolledIndeterminate))
      }
      nativeButton={nativeButton ?? render === undefined}
      onCheckedChange={handleCheckedChange}
      render={render ?? renderRoot}
    >
      <motion.span className="contents" {...separated.motion}>
        {children}
        <CheckboxPrimitive.Indicator className="group/indicator size-3.5" keepMounted render={<span />}>
          <svg
            aria-hidden="true"
            className="size-3.5"
            data-slot="checkbox-indicator"
            fill="none"
            stroke="currentColor"
            strokeWidth="3.5"
            viewBox="0 0 24 24"
          >
            <path
              className={cn(
                pathDrawClassName,
                'group-data-checked/indicator:opacity-100 group-data-checked/indicator:[stroke-dashoffset:0] group-data-indeterminate/indicator:hidden'
              )}
              d="M4.5 12.75l6 6 9-13.5"
              pathLength={1}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              className={cn(
                pathDrawClassName,
                'group-data-indeterminate/indicator:opacity-100 group-data-indeterminate/indicator:[stroke-dashoffset:0]'
              )}
              d="M5 12h14"
              pathLength={1}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </CheckboxPrimitive.Indicator>
      </motion.span>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox, type CheckboxProps, checkboxVariants };

import { Radio as RadioGroupPrimitive } from '@base-ui/react/radio';
import { Circle } from 'lucide-react';
import { AnimatePresence, motion, type Transition } from 'motion/react';
import { type ComponentProps, forwardRef, type HTMLAttributes } from 'react';

import { Card, CardContent, CardDescription, CardHeader, type CardProps, CardTitle } from '@/components/ui/card';
import { RadioGroup } from '@/components/ui/radio-group';
import { renderWithDataState } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const DEFAULT_TRANSITION = { damping: 16, stiffness: 200, type: 'spring' } satisfies Transition;

export type ChoiceboxProps = ComponentProps<typeof RadioGroup> & SharedProps;

export const Choicebox = ({ className, testId, ...props }: ChoiceboxProps) => (
  <RadioGroup className={cn('w-full', className)} data-testid={testId} {...props} />
);

export type ChoiceboxItemProps = ComponentProps<typeof RadioGroupPrimitive.Root> &
  SharedProps &
  Partial<Pick<CardProps, 'size'>>;

export const ChoiceboxItem = forwardRef<HTMLButtonElement, ChoiceboxItemProps>(
  ({ className, children, testId, size, ...props }, ref) => (
    <RadioGroupPrimitive.Root
      {...props}
      className="group"
      nativeButton
      ref={ref}
      render={renderWithDataState('button')}
    >
      <Card
        className={cn('flex cursor-pointer flex-row items-start justify-between text-left', className)}
        data-testid={testId}
        size={size}
        variant="choice"
      >
        {children}
      </Card>
    </RadioGroupPrimitive.Root>
  )
);

ChoiceboxItem.displayName = 'ChoiceboxItem';

export type ChoiceboxItemHeaderProps = ComponentProps<typeof CardHeader>;

export const ChoiceboxItemHeader = ({ className, ...props }: ComponentProps<typeof CardHeader>) => (
  <CardHeader className={cn('flex-1', className)} {...props} />
);

export type ChoiceboxItemTitleProps = ComponentProps<typeof CardTitle>;

export const ChoiceboxItemTitle = ({ className, ...props }: ChoiceboxItemTitleProps) => (
  <CardTitle className={cn('flex items-center', className)} spacing="loose" {...props} />
);

export type ChoiceboxItemSubtitleProps = HTMLAttributes<HTMLSpanElement>;

export const ChoiceboxItemSubtitle = ({ className, ...props }: ChoiceboxItemSubtitleProps) => (
  <span className={cn('text-xs font-normal text-muted-foreground', className)} {...props} />
);

export type ChoiceboxItemDescriptionProps = ComponentProps<typeof CardDescription>;

export const ChoiceboxItemDescription = ({ className, ...props }: ChoiceboxItemDescriptionProps) => (
  <CardDescription className={className} {...props} />
);

export type ChoiceboxItemContentProps = ComponentProps<typeof CardContent>;

export const ChoiceboxItemContent = ({ className, ...props }: ChoiceboxItemContentProps) => (
  <CardContent className={className} variant="selection-indicator" {...props} />
);

export type ChoiceboxItemIndicatorProps = ComponentProps<typeof RadioGroupPrimitive.Indicator> & {
  transition?: Transition;
};

export const ChoiceboxItemIndicator = ({
  className,
  transition = DEFAULT_TRANSITION,
  ...props
}: ChoiceboxItemIndicatorProps) => (
  <RadioGroupPrimitive.Indicator
    className={cn('flex items-center justify-center data-[unchecked]:hidden', className)}
    data-slot="radio-group-indicator"
    {...props}
  >
    <AnimatePresence>
      <motion.div
        animate={{ opacity: 1, scale: 1 }}
        data-slot="radio-group-indicator-circle"
        exit={{ opacity: 0, scale: 0.95 }}
        initial={{ opacity: 0, scale: 0.95 }}
        key="radio-group-indicator-circle"
        transition={transition}
      >
        <Circle className="size-2.5 fill-current text-current" />
      </motion.div>
    </AnimatePresence>
  </RadioGroupPrimitive.Indicator>
);

'use client';

import { Collapsible as CollapsiblePrimitive } from '@base-ui/react/collapsible';
import { AnimatePresence, type HTMLMotionProps, motion, type Transition } from 'motion/react';
import React from 'react';

import { asChildToRender, asChildTrigger, splitMotionProps } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';

const DEFAULT_TRANSITION = { damping: 22, stiffness: 150, type: 'spring' } satisfies Transition;

interface CollapsibleContextType {
  isOpen: boolean;
}

const CollapsibleContext = React.createContext<boolean | undefined>(undefined);

const useCollapsible = (): CollapsibleContextType => {
  const context = React.useContext(CollapsibleContext);
  if (context === undefined) {
    throw new Error('useCollapsible must be used within a Collapsible');
  }
  return { isOpen: context };
};

type CollapsibleProps = React.ComponentProps<typeof CollapsiblePrimitive.Root> &
  SharedProps & {
    asChild?: boolean;
  };

function Collapsible({ children, testId, asChild, onOpenChange, open, defaultOpen, ...props }: CollapsibleProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false);
  const isOpen = open ?? uncontrolledOpen;

  const handleOpenChange: NonNullable<CollapsiblePrimitive.Root.Props['onOpenChange']> = (nextOpen, details) => {
    onOpenChange?.(nextOpen, details);
    if (details.isCanceled) {
      return;
    }
    if (open === undefined) {
      setUncontrolledOpen(nextOpen);
    }
  };

  return (
    <CollapsibleContext.Provider value={isOpen}>
      <CollapsiblePrimitive.Root
        data-slot="collapsible"
        data-testid={testId}
        {...props}
        defaultOpen={defaultOpen}
        open={open}
        {...asChildToRender({ asChild, children })}
        onOpenChange={handleOpenChange}
      />
    </CollapsibleContext.Provider>
  );
}

type CollapsibleTriggerProps = React.ComponentProps<typeof CollapsiblePrimitive.Trigger> & {
  asChild?: boolean;
};

function CollapsibleTrigger({ className, ...props }: CollapsibleTriggerProps) {
  return (
    <CollapsiblePrimitive.Trigger
      className={(state) => cn('cursor-pointer', typeof className === 'function' ? className(state) : className)}
      data-slot="collapsible-trigger"
      {...asChildTrigger(props)}
    />
  );
}

type CollapsibleContentProps = React.ComponentProps<typeof CollapsiblePrimitive.Panel> &
  Omit<HTMLMotionProps<'div'>, keyof React.ComponentProps<typeof CollapsiblePrimitive.Panel>> & {
    transition?: Transition;
  };

function CollapsibleContent({
  className,
  children,
  render,
  keepMounted = false,
  transition = DEFAULT_TRANSITION,
  ...props
}: CollapsibleContentProps) {
  const { isOpen } = useCollapsible();
  const separated = splitMotionProps(props);

  return (
    <AnimatePresence>
      {isOpen || keepMounted === true ? (
        <CollapsiblePrimitive.Panel
          className={className}
          data-slot="collapsible-content"
          keepMounted
          render={render}
          {...separated.native}
        >
          <motion.div
            animate={{ height: 'auto', opacity: 1, overflow: 'hidden' }}
            exit={{ height: 0, opacity: 0, overflow: 'hidden' }}
            initial={{ height: 0, opacity: 0, overflow: 'hidden' }}
            layout
            transition={transition}
            {...separated.motion}
          >
            {children}
          </motion.div>
        </CollapsiblePrimitive.Panel>
      ) : null}
    </AnimatePresence>
  );
}

